// ── escaping ────────────────────────────────────────────────────────────────

const ESC_TEST = /[&<>"']/;
const ESC_ALL = /[&<>"']/g;
const ESC_MAP: Record<string, string> = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
const escRep = (c: string): string => ESC_MAP[c]!;
export function esc(s: string): string {
  return ESC_TEST.test(s) ? s.replace(ESC_ALL, escRep) : s;
}

const URL_STRIP_LEAD = /^[\u0000- ]+/;
const URL_STRIP_INNER = /[\t\n\r]/g;
const URL_SCHEME = /^([a-zA-Z][a-zA-Z0-9+.-]*):/;
const SAFE_SCHEMES = new Set(["http", "https", "mailto", "tel", "sms"]);
const SAFE_DATA = /^data:(image\/(?!svg)[a-z0-9.+-]+|audio\/[a-z0-9.+-]+|video\/[a-z0-9.+-]+|font\/[a-z0-9.+-]+)[;,]/i;

/** A URL with a scheme outside the allow-list is neutralised with an `unsafe:` prefix. */
export function safeUrl(raw: string): string {
  if (raw.charCodeAt(0) === 47) return raw; // "/…" has no scheme
  const probe = raw.replace(URL_STRIP_LEAD, "").replace(URL_STRIP_INNER, "");
  const m = URL_SCHEME.exec(probe);
  if (m === null) return raw;
  const scheme = m[1]!.toLowerCase();
  if (SAFE_SCHEMES.has(scheme)) return raw;
  if (scheme === "data" && SAFE_DATA.test(probe)) return raw;
  return "unsafe:" + probe;
}

const HX_URL_OK = /^(?:\/|\?|#|\.\.?\/|https?:\/\/)/;
function hxUrl(v: unknown, attr: string): string {
  if (v instanceof Url) return esc(v.href);
  if (typeof v === "string" && HX_URL_OK.test(v)) return esc(v);
  throw new TemplateError(`${attr} takes a route or a URL starting with "/", "?", "#" or "https://"; got ${show(v)}`);
}

const HX_JS_PREFIX = /^\s*(?:js|javascript):/i;

const CSS_VALUE_OK = /^[a-zA-Z0-9#%.,()\/ +_-]*$/;
const CSS_FN = /([a-zA-Z-]+)\(/g;
const CSS_FN_OK = new Set(["rgb", "rgba", "hsl", "hsla", "hwb", "lab", "lch", "oklab", "oklch", "color", "color-mix", "light-dark", "calc", "min", "max", "clamp", "var"]);
