    const v = decls[k];
    if (v === null || v === undefined || v === false) continue;
    if (!CSS_PROP.test(k)) throw new TemplateError(`not a CSS property name: ${show(k)}`);
    s += (s === "" ? "" : "; ") + k + ": " + cssValue(v);
